function validate([nums]) {
  if (!Array.isArray(nums) || nums.length < 1 || nums.length > 1000) return 'nums needs 1 to 1000 values.';
  if (nums.some(v => !Number.isInteger(v) || v < 1 || v > 10000)) return 'Each value is an integer from 1 to 10000.';
  if (new Set(nums).size !== nums.length) return 'The values must be distinct.';
  return null;
}

