function generate(rand, size) {
  const distinct = (n, top) => {
    const pool = Array.from({ length: top }, (_, i) => i + 1);
    for (let i = pool.length - 1; i > 0; i--) { const j = Math.floor(rand() * (i + 1)); [pool[i], pool[j]] = [pool[j], pool[i]]; }
    return pool.slice(0, n);
  };
  if (size === 'small') {
    const top = rand() < 0.7 ? 12 + Math.floor(rand() * 20) : 10000;
    const n = 1 + Math.floor(rand() * Math.min(10, top));
    return [distinct(n, top)];
  }
  const n = 700 + Math.floor(rand() * 301);
  const top = rand() < 0.5 ? 10000 : n + Math.floor(rand() * 500);
  return [distinct(n, top)];
}
